import numpy as np
from collections import Counter
M=37
PHI=(1<<37)-1; DEG=36
def gf2_mod(r):
    while r.bit_length()>DEG:
        r^=PHI<<(r.bit_length()-1-DEG)
    return r
def gf2_mul(a,b):
    r=0
    while b:
        if b&1: r^=a
        b>>=1; a<<=1
    return gf2_mod(r)
def gf2_pow(a,e):
    r=1
    while e:
        if e&1: r=gf2_mul(r,a)
        a=gf2_mul(a,a); e>>=1
    return r
def zeta_pow(m):
    m%=37
    return (1<<m) if m<=35 else (1<<36)-1

def orbit(a,b):
    s=set()
    for (p,q) in [(a,b),(-a,b),(a,-b),(-a,-b),(b,a),(-b,a),(b,-a),(-b,-a)]: s.add((p%M,q%M))
    return s
def build(sets):
    c=Counter()
    for (a,b) in sets:
        for p in orbit(a,b): c[p]+=1
    mat=np.zeros((M,M),dtype=np.uint8)
    for p,n in c.items():
        if n%2: mat[p]=1
    return mat
