for a in range(0,19):
    for b in range(a,19):
        reps.append((a,b))
def build(sets):
    c=Counter()
    for (a,b) in sets:
        for p in orbit(a,b): c[p]+=1
    mat=np.zeros((M,M),dtype=np.uint8)
    for p,n in c.items():
        if n%2: mat[p]=1
    return mat
